output.sparql:
SELECT ?player ?playerLabel ?nickname WHERE {
  wd:Q4241536 wdt:P31 wd:Q223222.
  ?player wdt:P31 wd:Q57163;
          wdt:P2211 ?position1;
          wdt:P2211 ?position2.
  FILTER(?position1 != ?position2)
  ?player rdfs:label ?playerLabel.
  FILTER(LANG(?playerLabel) = "en")
  OPTIONAL { ?player wdt:P755 ?nickname. }
  FILTER(LANG(?nickname) = "en")
  LIMIT 1
}

